constexpr uint32_t kUrmaWriteRegressionJettyNum = 0;
constexpr uint32_t kUrmaWriteRegressionTaskId = 9001;
constexpr uint32_t kUrmaReadRegressionJettyNum = 1;
constexpr uint32_t kUrmaReadRegressionTaskId = 9002;
constexpr uint32_t kUrmaReadMultiPacketTaskId = 9003;
constexpr uint32_t kUrmaWriteRegressionSenderTpn = 101;
constexpr uint32_t kUrmaWriteRegressionReceiverTpn = 202;
constexpr auto kUrmaWriteRegressionPriority = UB_PRIORITY_DEFAULT;

Ptr<UbWqeSegment>
CreateCtpWriteSegment(uint32_t taSsn = 0)
{
    Ptr<UbWqeSegment> segment = CreateObject<UbWqeSegment>();
    segment->SetSrc(0);
    segment->SetDest(1);
    segment->SetSport(CTP_WILDCARD_PORT);
    segment->SetDport(CTP_WILDCARD_PORT);
    segment->SetPriority(7);
    segment->SetType(UbTransactionOpcode::WRITE);
    segment->SetSize(64);
    segment->SetTaSsn(taSsn);
    segment->SetSegmentKind(UbTransactionSegmentKind::REQUEST);
    segment->SetPayloadBytes(64);
    segment->SetResLenBytes(64);
    segment->SetRemoteAddress(0);
    segment->SetCtpRequesterIdentity(0, 1);
    return segment;
}

Ptr<UbWqe>
CreateCtpWqeForKey(Ptr<UbFunction> function,
                   uint32_t srcNodeId,
                   const UbCtpEntityKey& key,
                   uint32_t requestId)
{
    Ptr<UbWqe> wqe = function->CreateWqe(srcNodeId,
                                         key.dstNodeId,
                                         64,
                                         requestId,
                                         UbTransactionOpcode::WRITE);
    wqe->SetSrcEntityId(key.srcEntityId);
    wqe->SetDstEntityId(key.dstEntityId);
    wqe->SetSport(CTP_WILDCARD_PORT);
    wqe->SetDport(CTP_WILDCARD_PORT);
    wqe->SetPriority(key.vl);
    return wqe;
}

Ptr<UbWqeSegment>
CreateCtpTaAckResponseSegment(uint32_t requestTaSsn)
{
    Ptr<UbWqeSegment> segment = CreateObject<UbWqeSegment>();
    segment->SetSrc(1);
    segment->SetDest(0);
    segment->SetSport(0);
    segment->SetDport(0);
    segment->SetPriority(7);
    segment->SetType(UbTransactionOpcode::TAACK);
    segment->SetSize(0);
    segment->SetTaSsn(requestTaSsn);
    segment->SetSegmentKind(UbTransactionSegmentKind::RESPONSE);
    segment->SetRequestTassn(requestTaSsn);
    segment->SetRequestOpcode(UbTransactionOpcode::WRITE);
    segment->SetPayloadBytes(0);
    segment->SetResLenBytes(0);
    segment->SetRemoteAddress(0);
    segment->SetCtpRequesterIdentity(0, 1);
    return segment;
}

Ptr<Packet>
BuildCtpCnpPacket(uint32_t srcNodeId, const UbCtpEntityKey& key)
{
    Ptr<Packet> packet = Create<Packet>();

    UbCompactEidHeader eidHeader;
    eidHeader.SetSourceEid(key.srcEntityId);
    eidHeader.SetDestinationEid(key.dstEntityId);
    packet->AddHeader(eidHeader);

    UbCompactUpiHeader upiHeader;
    upiHeader.SetUpi(0);
    packet->AddHeader(upiHeader);

    UbCtpHeader ctpHeader;
    ctpHeader.SetTPOpcode(CtpOpcode::CTP_CNP);
    ctpHeader.SetNlp(UB_CTPH_NLP_UPI16_EID40_TAH);
    packet->AddHeader(ctpHeader);

    UbCna16NetworkHeader cnaHeader;
    cnaHeader.SetScna(static_cast<uint16_t>(NodeIdToCna16(srcNodeId)));
    cnaHeader.SetDcna(static_cast<uint16_t>(NodeIdToCna16(key.dstNodeId)));
    cnaHeader.SetServiceLevel(key.vl);
    cnaHeader.SetNlp(UB_CNA_NLP_CTPH);
    packet->AddHeader(cnaHeader);

    UbDataLink::AddPacketHeader(packet,
                                false,
                                false,
                                key.vl,
                                key.vl,
                                RoutingType::PER_FLOW_SHORTEST_PATHS,
                                UbDatalinkHeaderConfig::PACKET_CNA16);
    return packet;
}

Ptr<Packet>
BuildCtpResponsePacketFromNode(Ptr<Node> sourceNode,
                               Ptr<UbWqeSegment> response,
                               const UbCtpEntityKey& key)
{
    Ptr<UbCtpTransportService> sourceService = CreateObject<UbCtpTransportService>();
    sourceService->SetNode(sourceNode);
    return sourceService->BuildResponsePacketForTest(response, key);
}

