        NS_TEST_ASSERT_MSG_EQ(copied, bytes.size(), "serialized 64-bit SAETPH should be 12 bytes");
        NS_TEST_ASSERT_MSG_EQ(bytes[0], 0u, "64-bit SAETPH should use encoded bitmap size 0");
