#ifndef _WIN32
int
RunInChildProcess(const std::function<void()>& fn)
{
    pid_t pid = fork();
    if (pid == -1)
    {
        return -1;
    }

    if (pid == 0)
    {
        fn();
        std::_Exit(0);
    }

    int status = 0;
    int waitRet = waitpid(pid, &status, 0);
    if (waitRet == -1)
    {
        return -1;
    }
    return status;
}
#endif

