class UbExplicitTpDestroyDrainsAndRematerializesTest : public TestCase
{
  public:
    UbExplicitTpDestroyDrainsAndRematerializesTest()
        : TestCase("UnifiedBus - explicit TP destroy drains and preserves reservation")
    {
    }

  private:
    void OnDestroyed(UbLifecycleResourceIdentity identity, UbDestroyStatus status)
    {
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(status),
                              static_cast<uint32_t>(UbDestroyStatus::COMPLETED),
                              "Destroy callback should report completion");
        NS_TEST_ASSERT_MSG_EQ(m_controller->GetTransportChannelManager()->GetTp(static_cast<uint32_t>(identity.localId)),
                              nullptr,
                              "Destroy callback should run after canonical endpoint erase");
        m_callbackIdentity = identity;
        ++m_callbackCount;
    }

    void DoRun() override
    {
        Config::Reset();
        GlobalValue::Bind("UB_CC_ENABLED", BooleanValue(true));
        GlobalValue::Bind("UB_CC_ALGO", StringValue("DCQCN"));
        LocalTpTopology topo = BuildLocalTpTopology();
        Ptr<UbController> sender = topo.sender->GetObject<UbController>();
        m_controller = topo.receiver->GetObject<UbController>();
        sender->GetTpConnManager()->ReserveTpnsForTraffic(true,
                                                          topo.sender->GetId(),
                                                          topo.receiver->GetId(),
                                                          kUrmaWriteRegressionPriority);
        const auto receiverTpns = m_controller->GetTpConnManager()->GetTpnsByPeerNodePriority(
            topo.receiver->GetId(),
            topo.sender->GetId(),
            kUrmaWriteRegressionPriority);
        NS_TEST_ASSERT_MSG_EQ(receiverTpns.size(), 1u, "Expected one receiver reservation");
        const uint32_t tpn = receiverTpns[0].first;
        const auto senderTpns = sender->GetTpConnManager()->GetTpnsByPeerNodePriority(
            topo.sender->GetId(), topo.receiver->GetId(), kUrmaWriteRegressionPriority);
        NS_TEST_ASSERT_MSG_EQ(senderTpns.size(), 1u, "Expected one sender reservation");
        ConnectionLifecycleSnapshot connectionSnapshot;
        NS_TEST_ASSERT_MSG_EQ(sender->GetTpConnManager()->GetCanonicalConnectionCountForTest(),
                              1u,
                              "Reservation should create one canonical owner record");
        NS_TEST_ASSERT_MSG_EQ(sender->GetTpConnManager()->GetConnectionLifecycleSnapshot(
                                  senderTpns[0].first, connectionSnapshot),
                              true,
                              "Owner should expose the reserved connection generation");
        NS_TEST_ASSERT_MSG_EQ(connectionSnapshot.ownerNodeId,
                              topo.sender->GetId(),
                              "Connection owner should be the canonical source node");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(connectionSnapshot.slot1),
                              static_cast<uint32_t>(EndpointSlotState::UNMATERIALIZED),
                              "Source slot should begin unmaterialized");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(connectionSnapshot.slot2),
                              static_cast<uint32_t>(EndpointSlotState::UNMATERIALIZED),
                              "Receiver slot should begin unmaterialized");
        Ptr<UbTransportChannel> first = m_controller->GetTransportChannelManager()->CreateReservedTpEndpoint(tpn);
        NS_TEST_ASSERT_MSG_NE(first, nullptr, "Reserved endpoint should materialize");
        NS_TEST_ASSERT_MSG_EQ(sender->GetTpConnManager()->GetConnectionLifecycleSnapshot(
                                  senderTpns[0].first, connectionSnapshot),
                              true,
                              "Owner snapshot should remain available after one endpoint materializes");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(connectionSnapshot.slot1),
                              static_cast<uint32_t>(EndpointSlotState::UNMATERIALIZED),
                              "Source slot should remain unmaterialized");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(connectionSnapshot.slot2),
                              static_cast<uint32_t>(EndpointSlotState::ACTIVE),
                              "Receiver slot should become active when materialized");
        const UbLifecycleResourceIdentity firstIdentity = first->GetLifecycleOwner();

        Ptr<UbLifecycleCoordinator> coordinator =
            UbLifecycleCoordinator::GetOrCreate(topo.receiver);
        const UbLifecycleLeaseIdentity gate = coordinator->AcquireLease(
            firstIdentity,
            UbLifecycleLeaseKind::TRANSPORT_WORK,
            firstIdentity);
        const UbDestroyStatus pending = m_controller->GetTransportChannelManager()->DestroyTp(
            tpn,
            UbDestroyReason::EXPLICIT,
            MakeCallback(&UbExplicitTpDestroyDrainsAndRematerializesTest::OnDestroyed, this));
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(pending),
                              static_cast<uint32_t>(UbDestroyStatus::PENDING),
                              "Active lifecycle work should defer endpoint finalization");
        NS_TEST_ASSERT_MSG_EQ(m_controller->GetTransportChannelManager()->GetTp(tpn),
                              first,
                              "Pending destroy should retain the canonical endpoint");
        NS_TEST_ASSERT_MSG_EQ(first->CanAdmitWqeSegment(nullptr),
                              false,
                              "Destroy request should freeze new segment admission");
        const UbTpQuiescenceAssessment drainingDestroy =
            m_controller->GetTransportChannelManager()->AssessTpQuiescence(tpn);
        NS_TEST_ASSERT_MSG_EQ(
            drainingDestroy.HasBlocker(UbTpQuiescenceBlocker::ACTIVE_TRANSPORT_WORK_LEASE),
            true,
            "A real draining endpoint should retain the typed lifecycle blocker");
        NS_TEST_ASSERT_MSG_EQ(
            drainingDestroy.HasBlocker(UbTpQuiescenceBlocker::ENDPOINT_NOT_DRAINING),
            false,
            "Explicit-destroy assessment should observe the real DRAINING state");
        coordinator->ReleaseLease(gate);
        NS_TEST_ASSERT_MSG_EQ(m_callbackCount, 1u, "Pending callback should run exactly once");
        NS_TEST_ASSERT_MSG_EQ(m_controller->GetTransportChannelManager()->GetTp(tpn),
                              nullptr,
                              "Last lifecycle release should finalize without a second destroy");
        NS_TEST_ASSERT_MSG_EQ(m_callbackIdentity,
                              firstIdentity,
                              "Destroy callback should identify the retired generation");
        NS_TEST_ASSERT_MSG_EQ(m_controller->GetTpConnManager()->TryGetLocalConnection(
                                  topo.receiver->GetId(), tpn, m_connection),
                              true,
                              "Local endpoint destroy should preserve its reservation");

        Ptr<UbTransportChannel> second = m_controller->GetTransportChannelManager()->CreateReservedTpEndpoint(tpn);
        NS_TEST_ASSERT_MSG_NE(second, nullptr, "Later demand should rematerialize the endpoint");
        NS_TEST_ASSERT_MSG_NE(second->GetLifecycleOwner().generation,
                              firstIdentity.generation,
                              "Rematerialization should open a new endpoint generation");
        Ptr<UbHostDcqcn> secondCc =
            DynamicCast<UbHostDcqcn>(second->GetCongestionCtrlForTest());
        NS_TEST_ASSERT_MSG_NE(secondCc, nullptr, "Rematerialized TP should use configured DCQCN");
        (void)secondCc->IsCcLimited(1);
        secondCc->ApplySyntheticCnpForTest();
        const UbDestroyStatus eventDrain = m_controller->GetTransportChannelManager()->DestroyTp(
            tpn,
            UbDestroyReason::EXPLICIT,
            MakeCallback(&UbExplicitTpDestroyDrainsAndRematerializesTest::OnDestroyed, this));
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(eventDrain),
                              static_cast<uint32_t>(UbDestroyStatus::COMPLETED),
                              "Destroy freeze should cancel endpoint-only DCQCN events");
        NS_TEST_ASSERT_MSG_EQ(m_callbackCount,
                              2u,
                              "Tracked-event cancellation should finalize reentrantly once");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(m_controller->GetTransportChannelManager()->DestroyTp(999999)),
                              static_cast<uint32_t>(UbDestroyStatus::NOT_FOUND),
                              "Destroying an unknown TPN should not insert an endpoint");

        Simulator::Destroy();
        Config::Reset();
    }

    Ptr<UbController> m_controller;
    Connection m_connection;
    UbLifecycleResourceIdentity m_callbackIdentity;
    uint32_t m_callbackCount{0};
};

class UbTpQuiescenceAssessmentReportsTypedBlockersTest : public TestCase
{
  public:
    UbTpQuiescenceAssessmentReportsTypedBlockersTest()
        : TestCase("UnifiedBus - explicit TP close assessment reports owner-local blockers")
    {
    }

  private:
    void DoRun() override
    {
        Config::Reset();
        LocalTpTopology topo = BuildLocalTpTopology();
        Ptr<UbController> sender = topo.sender->GetObject<UbController>();
        Ptr<UbController> receiver = topo.receiver->GetObject<UbController>();
        sender->GetTpConnManager()->ReserveTpnsForTraffic(true,
                                                          topo.sender->GetId(),
                                                          topo.receiver->GetId(),
                                                          kUrmaWriteRegressionPriority);
        const auto receiverTpns =
            receiver->GetTpConnManager()->GetTpnsByPeerNodePriority(topo.receiver->GetId(),
                                                                    topo.sender->GetId(),
                                                                    kUrmaWriteRegressionPriority);
        NS_TEST_ASSERT_MSG_EQ(receiverTpns.size(), 1u, "Expected one receiver reservation");
        const uint32_t tpn = receiverTpns[0].first;
        Ptr<UbTransportChannelManager> manager = receiver->GetTransportChannelManager();
        Ptr<UbTransportChannel> tp = manager->CreateReservedTpEndpoint(tpn);
        NS_TEST_ASSERT_MSG_NE(tp, nullptr, "Reserved endpoint should materialize");

        UbTpQuiescenceAssessment assessment = manager->AssessTpQuiescence(tpn);
        NS_TEST_ASSERT_MSG_EQ(
            assessment.HasBlocker(UbTpQuiescenceBlocker::ENDPOINT_NOT_DRAINING),
            true,
            "Explicit close assessment should require the drain phase");
        NS_TEST_ASSERT_MSG_EQ(assessment.identity,
                              tp->GetLifecycleOwner(),
                              "Assessment should report the exact endpoint generation");
        NS_TEST_ASSERT_MSG_EQ(manager->PeekLiveTp(tpn),
                              tp,
                              "Read-only assessment must retain the endpoint");

        tp->EnqueueAckForTest(Create<Packet>(1));
        tp->EnqueueCnpForTest(Create<Packet>(1));
        tp->PushWqeSegment(CreateObject<UbWqeSegment>());
        tp->AddRemoteRequestForTest(CreateObject<UbWqeSegment>());
        tp->AddInboundTaUnitForTest(7, 11);
        tp->AddBufferedInboundPacketForTest(13);
        tp->SetPsnSndUnaForTest(17);
        tp->SetPsnSndNxtForTest(18);
        assessment = manager->AssessTpQuiescence(tpn);
        NS_TEST_ASSERT_MSG_EQ(assessment.HasBlocker(UbTpQuiescenceBlocker::ACK_QUEUE),
                              true,
                              "Pending ACK work should block explicit close");
        NS_TEST_ASSERT_MSG_EQ(assessment.HasBlocker(UbTpQuiescenceBlocker::CNP_QUEUE),
                              true,
                              "Pending CNP work should block explicit close");
        NS_TEST_ASSERT_MSG_EQ(assessment.HasBlocker(UbTpQuiescenceBlocker::WQE_SEGMENT_QUEUE),
                              true,
                              "Pending WQE work should block explicit close");
        NS_TEST_ASSERT_MSG_EQ(assessment.HasBlocker(UbTpQuiescenceBlocker::REMOTE_REQUEST),
                              true,
                              "Pending remote work should block explicit close");
        NS_TEST_ASSERT_MSG_EQ(assessment.HasBlocker(UbTpQuiescenceBlocker::INBOUND_WORK),
                              true,
                              "Pending inbound work should block explicit close");
        NS_TEST_ASSERT_MSG_EQ(
            assessment.HasBlocker(UbTpQuiescenceBlocker::BUFFERED_INBOUND_PACKET),
            true,
            "Buffered inbound data should block explicit close");
        NS_TEST_ASSERT_MSG_EQ(assessment.HasBlocker(UbTpQuiescenceBlocker::UNACKNOWLEDGED_PSN),
                              true,
                              "An unacknowledged PSN range should block explicit close");

        const UbTpQuiescenceAssessment missing = manager->AssessTpQuiescence(tpn + 1000000);
        NS_TEST_ASSERT_MSG_EQ(missing.HasBlocker(UbTpQuiescenceBlocker::ENDPOINT_MISSING),
                              true,
                              "A missing endpoint should fail closed");

        Simulator::Destroy();
        Config::Reset();
    }
};

class UbTpQuiescenceAssessmentReportsTransactionReferencesTest : public TestCase
{
  public:
    UbTpQuiescenceAssessmentReportsTransactionReferencesTest()
        : TestCase("UnifiedBus - TP quiescence reports direct, TPG, and remote transaction blockers")
    {
    }

  private:
    void DoRun() override
    {
        CheckDirectReference();
        CheckTpgMemberReference();
        CheckRemoteTransportWork();
    }

    void CheckDirectReference()
    {
        Config::Reset();
        LocalTpTopology topo = BuildLocalTpTopology();
        InstallStaticTpPair(topo);
        Ptr<UbController> controller = topo.sender->GetObject<UbController>();
        Ptr<UbTransportChannelManager> manager = controller->GetTransportChannelManager();
        constexpr uint32_t jettyNum = kUrmaWriteRegressionJettyNum + 201;
        controller->GetUbFunction()->CreateJetty(topo.sender->GetId(),
                                                 topo.receiver->GetId(),
                                                 jettyNum);
        NS_TEST_ASSERT_MSG_EQ(controller->GetUbTransaction()->JettyBindTp(
                                  topo.sender->GetId(),
                                  topo.receiver->GetId(),
                                  jettyNum,
                                  false,
                                  {kUrmaWriteRegressionSenderTpn}),
                              true,
                              "Direct-reference fixture should bind one TP");
        const UbTpQuiescenceAssessment assessment =
            manager->AssessTpQuiescence(kUrmaWriteRegressionSenderTpn);
        NS_TEST_ASSERT_MSG_EQ(
            assessment.HasBlocker(UbTpQuiescenceBlocker::TRANSACTION_REFERENCE),
            true,
            "A direct RTP transport reference should report its typed blocker");
        NS_TEST_ASSERT_MSG_EQ(assessment.diagnostics.transactionReferenced,
                              true,
                              "Direct reference diagnostics should report the real transaction fact");
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(controller->GetUbFunction()->DestroyJetty(jettyNum)),
            static_cast<uint32_t>(UbDestroyStatus::COMPLETED),
            "Direct-reference fixture should clean its Jetty binding");
        Simulator::Destroy();
        Config::Reset();
    }

    void CheckTpgMemberReference()
    {
        Config::Reset();
        LocalTpTopology topo = BuildLocalTpTopology();
        InstallStaticTpPair(topo);
        InstallAdditionalTpPair(topo, 303, 404);
        Ptr<UbController> controller = topo.sender->GetObject<UbController>();
        Ptr<UbTransportChannelManager> manager = controller->GetTransportChannelManager();
        constexpr uint32_t jettyNum = kUrmaWriteRegressionJettyNum + 202;
        controller->GetUbFunction()->CreateJetty(topo.sender->GetId(),
                                                 topo.receiver->GetId(),
                                                 jettyNum);
        NS_TEST_ASSERT_MSG_EQ(controller->GetUbTransaction()->JettyBindTp(
                                  topo.sender->GetId(),
                                  topo.receiver->GetId(),
                                  jettyNum,
                                  true,
                                  {kUrmaWriteRegressionSenderTpn, 303}),
                              true,
                              "TPG-reference fixture should bind two member TPs");
        const UbTpQuiescenceAssessment assessment =
            manager->AssessTpQuiescence(kUrmaWriteRegressionSenderTpn);
        NS_TEST_ASSERT_MSG_EQ(
            assessment.HasBlocker(UbTpQuiescenceBlocker::TRANSACTION_REFERENCE),
            true,
            "A TPG member reference should report its typed blocker");
        NS_TEST_ASSERT_MSG_EQ(
            assessment.HasBlocker(UbTpQuiescenceBlocker::ACTIVE_BINDING_LEASE),
            true,
            "Owner-local TPG membership should block explicit member TP close");
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(controller->GetUbFunction()->DestroyJetty(jettyNum)),
            static_cast<uint32_t>(UbDestroyStatus::COMPLETED),
            "TPG-reference fixture should clean its Jetty and group binding");
        Simulator::Destroy();
        Config::Reset();
    }

    void CheckRemoteTransportWork()
    {
        Config::Reset();
        LocalTpTopology topo = BuildLocalTpTopology();
        InstallStaticTpPair(topo);
        Ptr<UbController> controller = topo.sender->GetObject<UbController>();
        Ptr<UbTransportChannelManager> manager = controller->GetTransportChannelManager();
        Ptr<UbTransportChannel> tp = manager->PeekLiveTp(kUrmaWriteRegressionSenderTpn);
        NS_TEST_ASSERT_MSG_NE(tp, nullptr, "Remote-work fixture should have a materialized TP");
        tp->SetMaxQueueSizeForTest(0);
        tp->FreezeNewWork();
        Ptr<UbWqeSegment> request = CreateObject<UbWqeSegment>();
        request->SetSrc(topo.receiver->GetId());
        request->SetDest(topo.sender->GetId());
        request->SetType(UbTransactionOpcode::WRITE);
        request->SetRequestOpcode(UbTransactionOpcode::WRITE);
        request->SetSegmentKind(UbTransactionSegmentKind::REQUEST);
        request->SetOriginJettyNum(77);
        request->SetTaskId(88);
        request->SetSize(64);
        request->SetWqeSize(64);
        request->SetLogicalBytes(64);
        request->SetPayloadBytes(64);
        request->SetTransactionFields(
            UbTransactionFields{.memoryAccess = UbMemoryAccessFields{0, 0, 64}});
        // A carrier always caches the normalized result before the common target entry consumes it.
        UbTransactionRequestInput remoteInput;
        remoteInput.opcode = UbTransactionOpcode::WRITE;
        remoteInput.logicalBytes = 64;
        remoteInput.payloadBytes = 64;
        remoteInput.fields = request->GetTransactionFields();
        remoteInput.maxPayloadBytes = UINT32_MAX;
        remoteInput.origin = UbTransactionRequestOrigin::INBOUND_DECODE;
        const auto remoteValidation = ValidateTransactionRequest(remoteInput);
        NS_TEST_ASSERT_MSG_EQ(remoteValidation.IsValid(), true, remoteValidation.message);
        request->SetTransactionResolved(remoteValidation.resolved);
        controller->GetUbTransaction()->HandleInboundTaUnit(kUrmaWriteRegressionSenderTpn,
                                                            request);
        Simulator::Stop(TimeStep(1));
        Simulator::Run();
        const UbTpQuiescenceAssessment assessment =
            manager->AssessTpQuiescence(kUrmaWriteRegressionSenderTpn);
        NS_TEST_ASSERT_MSG_EQ(
            assessment.HasBlocker(UbTpQuiescenceBlocker::PENDING_TRANSPORT_WORK),
            true,
            "Capacity-blocked remote transaction work should report its typed blocker");
        NS_TEST_ASSERT_MSG_EQ(assessment.diagnostics.pendingTransportWork,
                              true,
                              "Remote-work diagnostics should report the real transaction fact");
        Simulator::Destroy();
        Config::Reset();
    }
};

#if defined(NS3_MTP) && !defined(_WIN32)
class UbTpResolutionMtpOwnershipReadinessTest : public TestCase
{
  public:
    UbTpResolutionMtpOwnershipReadinessTest()
        : TestCase("UnifiedBus - live TP resolution honors MTP ownership readiness")
    {
    }

    void DoRun() override
    {
        const int prePartitionStatus = RunInChildProcess([]() {
            const LiveEndpoint endpoint = PrepareLiveEndpoint();
            MtpInterface::Enable();
            if (endpoint.manager->CreateReservedTpEndpoint(endpoint.tpn) != endpoint.tp)
            {
                std::_Exit(2);
            }
            const UbInboundTpResolution inbound = endpoint.manager->ResolveInboundTp(
                endpoint.peerTpn,
                endpoint.tpn,
                endpoint.sourceIp,
                endpoint.destinationIp,
                endpoint.priority);
            if (inbound.state != UbInboundTpState::LIVE || inbound.endpoint != endpoint.tp ||
                endpoint.manager->ResolveLiveTp(endpoint.tpn, endpoint.identity) != endpoint.tp)
            {
                std::_Exit(3);
            }
        });
        NS_TEST_ASSERT_MSG_EQ(WIFEXITED(prePartitionStatus),
                              1,
                              "Pre-partition MTP resolution must not abort");
        NS_TEST_ASSERT_MSG_EQ(WEXITSTATUS(prePartitionStatus),
                              0,
                              "Pre-partition MTP should preserve the bootstrap path");

        const int missingOwnerStatus = RunInChildProcess([]() {
            const LiveEndpoint endpoint = PrepareLiveEndpoint();
            MtpInterface::Enable(1, 1);
            const UbInboundTpResolution inbound = endpoint.manager->ResolveInboundTp(
                endpoint.peerTpn,
                endpoint.tpn,
                endpoint.sourceIp,
                endpoint.destinationIp,
                endpoint.priority);
            const UbTpQuiescenceAssessment assessment =
                endpoint.manager->AssessTpQuiescence(endpoint.tpn);
            if (endpoint.manager->CreateReservedTpEndpoint(endpoint.tpn) != nullptr ||
                inbound.state != UbInboundTpState::INVALID || inbound.endpoint != nullptr ||
                endpoint.manager->ResolveLiveTp(endpoint.tpn, endpoint.identity) != nullptr ||
                !assessment.HasBlocker(UbTpQuiescenceBlocker::WRONG_EXECUTION_OWNER) ||
                endpoint.manager->PeekLiveTp(endpoint.tpn) != endpoint.tp)
            {
                std::_Exit(4);
            }
        });
        NS_TEST_ASSERT_MSG_EQ(WIFEXITED(missingOwnerStatus),
                              1,
                              "Missing partition ownership must fail closed without aborting");
        NS_TEST_ASSERT_MSG_EQ(WEXITSTATUS(missingOwnerStatus),
                              0,
                              "Missing ownership must not mutate the live endpoint");

        const int mappedOwnerStatus = RunInChildProcess([]() {
            const LiveEndpoint endpoint = PrepareLiveEndpoint();
            NodeList::GetNode(endpoint.identity.ownerNodeId)->SetSystemId(1);
            MtpInterface::Enable(1, 2);
            if (MtpInterface::RequireNodeLocalLpId(endpoint.identity.ownerNodeId) != 1)
            {
                std::_Exit(10);
            }
            MtpInterface::SetSystem(2);
            if (endpoint.manager->ResolveLiveTp(endpoint.tpn, endpoint.identity) != nullptr)
            {
                std::_Exit(11);
            }
            MtpInterface::SetSystem(0);
            if (endpoint.manager->ResolveLiveTp(endpoint.tpn, endpoint.identity) != nullptr)
            {
                std::_Exit(12);
            }
            MtpInterface::SetSystem(1);
            if (endpoint.manager->ResolveLiveTp(endpoint.tpn, endpoint.identity) != endpoint.tp)
            {
                std::_Exit(13);
            }
        });
        NS_TEST_ASSERT_MSG_EQ(WIFEXITED(mappedOwnerStatus),
                              1,
                              "Mapped MTP ownership checks must not abort");
        NS_TEST_ASSERT_MSG_EQ(WEXITSTATUS(mappedOwnerStatus),
                              0,
                              "Only the mapped worker may resolve the endpoint");

        const int drainingWrongOwnerStatus = RunInChildProcess([]() {
            const LiveEndpoint endpoint = PrepareLiveEndpoint();
            NodeList::GetNode(endpoint.identity.ownerNodeId)->SetSystemId(1);
            MtpInterface::Enable(1, 2);
            MtpInterface::SetSystem(1);
            Ptr<UbLifecycleCoordinator> coordinator = UbLifecycleCoordinator::GetOrCreate(
                NodeList::GetNode(endpoint.identity.ownerNodeId));
            const UbLifecycleLeaseIdentity lease = coordinator->AcquireLease(
                endpoint.identity,
                UbLifecycleLeaseKind::TRANSPORT_WORK,
                endpoint.identity);
            if (endpoint.manager->DestroyTp(endpoint.tpn) != UbDestroyStatus::PENDING)
            {
                std::_Exit(20);
            }
            MtpInterface::SetSystem(2);
            const UbInboundTpResolution inbound = endpoint.manager->ResolveInboundTp(
                endpoint.peerTpn,
                endpoint.tpn,
                endpoint.sourceIp,
                endpoint.destinationIp,
                endpoint.priority);
            if (inbound.state != UbInboundTpState::INVALID || inbound.endpoint != nullptr)
            {
                std::_Exit(21);
            }
            MtpInterface::SetSystem(1);
            coordinator->ReleaseLease(lease);
        });
        NS_TEST_ASSERT_MSG_EQ(WIFEXITED(drainingWrongOwnerStatus),
                              1,
                              "Wrong-owner draining ingress must not abort");
        NS_TEST_ASSERT_MSG_EQ(WEXITSTATUS(drainingWrongOwnerStatus),
                              0,
                              "Wrong-owner draining ingress must not expose the endpoint");
    }

  private:
    struct LiveEndpoint
    {
        Ptr<UbTransportChannelManager> manager;
        Ptr<UbTransportChannel> tp;
        uint32_t tpn{0};
        uint32_t peerTpn{0};
        Ipv4Address sourceIp;
        Ipv4Address destinationIp;
        UbPriority priority{UB_PRIORITY_DEFAULT};
        UbLifecycleResourceIdentity identity;
    };

    static LiveEndpoint PrepareLiveEndpoint()
    {
        Config::Reset();
        LocalTpTopology topo = BuildLocalTpTopology();
        Ptr<UbController> sender = topo.sender->GetObject<UbController>();
        Ptr<UbController> receiver = topo.receiver->GetObject<UbController>();
        sender->GetTpConnManager()->ReserveTpnsForTraffic(true,
                                                          topo.sender->GetId(),
                                                          topo.receiver->GetId(),
                                                          kUrmaWriteRegressionPriority);
        const auto receiverTpns =
            receiver->GetTpConnManager()->GetTpnsByPeerNodePriority(topo.receiver->GetId(),
                                                                    topo.sender->GetId(),
                                                                    kUrmaWriteRegressionPriority);
        if (receiverTpns.size() != 1)
        {
            std::_Exit(30);
        }
        LiveEndpoint endpoint;
        endpoint.manager = receiver->GetTransportChannelManager();
        endpoint.tpn = receiverTpns[0].first;
        endpoint.tp = endpoint.manager->CreateReservedTpEndpoint(endpoint.tpn);
        if (endpoint.tp == nullptr)
        {
            std::_Exit(31);
        }
        endpoint.peerTpn = endpoint.tp->GetDestTpn();
        endpoint.sourceIp = endpoint.tp->GetDip();
        endpoint.destinationIp = endpoint.tp->GetSip();
        endpoint.priority = static_cast<UbPriority>(endpoint.tp->GetPriority());
        endpoint.identity = endpoint.tp->GetLifecycleOwner();
        return endpoint;
    }
};
#endif

class UbTpnAllocationBoundaryTest : public TestCase
{
  public:
    UbTpnAllocationBoundaryTest()
        : TestCase("UnifiedBus - TPN allocation stops at the 24-bit wire boundary")
    {
    }

    void DoRun() override
    {
        Ptr<TpConnectionManager> manager = CreateObject<TpConnectionManager>();
        UbTpnAllocationBoundaryAccessor::SetNextTpn(manager, 0xFFFFFE);
        NS_TEST_ASSERT_MSG_EQ(manager->GetNextTpn(),
                              0xFFFFFEu,
                              "The penultimate wire TPN should remain allocatable");
        NS_TEST_ASSERT_MSG_EQ(manager->GetNextTpn(),
                              0xFFFFFFu,
                              "The final 24-bit wire TPN should remain allocatable");

#ifndef _WIN32
        const int exhaustedStatus = RunInChildProcess([]() {
            Ptr<TpConnectionManager> exhausted = CreateObject<TpConnectionManager>();
            UbTpnAllocationBoundaryAccessor::SetNextTpn(exhausted, 0xFFFFFF);
            if (exhausted->GetNextTpn() != 0xFFFFFFu)
            {
                std::_Exit(60);
            }
            exhausted->GetNextTpn();
            std::_Exit(61);
        });
        NS_TEST_ASSERT_MSG_EQ(WIFSIGNALED(exhaustedStatus),
                              1,
                              "Allocation after the final wire TPN must abort before wraparound");
        NS_TEST_ASSERT_MSG_EQ(WTERMSIG(exhaustedStatus),
                              SIGABRT,
                              "Allocation after the final wire TPN must fail with SIGABRT");

        const int occupiedFinalStatus = RunInChildProcess([]() {
            Ptr<TpConnectionManager> exhausted = CreateObject<TpConnectionManager>();
            UbTpnAllocationBoundaryAccessor::SetNextTpn(exhausted, 0xFFFFFF);
            UbTpnAllocationBoundaryAccessor::OccupyTpn(exhausted, 0xFFFFFF);
            exhausted->GetNextTpn();
            std::_Exit(62);
        });
        NS_TEST_ASSERT_MSG_EQ(WIFSIGNALED(occupiedFinalStatus),
                              1,
                              "An occupied final wire TPN must abort before incrementing");
        NS_TEST_ASSERT_MSG_EQ(WTERMSIG(occupiedFinalStatus),
                              SIGABRT,
                              "An occupied final wire TPN must fail with SIGABRT");
#endif
    }
};

class UbExplicitConnectionDestroyAggregatesBothEndpointsTest : public TestCase
{
  public:
    UbExplicitConnectionDestroyAggregatesBothEndpointsTest()
        : TestCase("UnifiedBus - explicit connection destroy aggregates both endpoints")
    {
    }

  private:
    void OnDestroyed(UbLifecycleResourceIdentity identity, UbDestroyStatus status)
    {
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(status),
                              static_cast<uint32_t>(UbDestroyStatus::COMPLETED),
                              "Connection callback should report completion");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(identity.kind),
                              static_cast<uint32_t>(UbLifecycleResourceKind::RTP_CONNECTION),
                              "Callback should identify the connection generation");
        Connection ignored;
        NS_TEST_ASSERT_MSG_EQ(m_senderManager->TryGetLocalConnection(
                                  m_connection.node1, m_connection.tpn1, ignored),
                              false,
                              "Connection callback should run after source reservation erase");
        NS_TEST_ASSERT_MSG_EQ(m_receiverManager->TryGetLocalConnection(
                                  m_connection.node2, m_connection.tpn2, ignored),
                              false,
                              "Connection callback should run after receiver reservation erase");
        NS_TEST_ASSERT_MSG_EQ(m_senderController->GetTransportChannelManager()->GetTp(m_connection.tpn1),
                              nullptr,
                              "Connection callback should observe source endpoint erase");
        NS_TEST_ASSERT_MSG_EQ(m_receiverController->GetTransportChannelManager()->GetTp(m_connection.tpn2),
                              nullptr,
                              "Connection callback should observe receiver endpoint erase");
        m_destroyedIdentity = identity;
        ++m_callbackCount;
    }

    void DoRun() override
    {
        LocalTpTopology topo = BuildLocalTpTopology();
        m_senderController = topo.sender->GetObject<UbController>();
        m_receiverController = topo.receiver->GetObject<UbController>();
        m_senderManager = m_senderController->GetTpConnManager();
        m_receiverManager = m_receiverController->GetTpConnManager();

        const std::vector<uint32_t> senderTpns = m_senderManager->GetTpns(
            utils::GetTpnRuleT::BY_PEERNODE_PRIORITY,
            true,
            false,
            topo.sender->GetId(),
            topo.receiver->GetId(),
            UINT32_MAX,
            UINT32_MAX,
            kUrmaWriteRegressionPriority);
        NS_TEST_ASSERT_MSG_EQ(senderTpns.size(), 1u, "Expected one materialized source endpoint");
        NS_TEST_ASSERT_MSG_EQ(m_senderManager->TryGetLocalConnection(
                                  topo.sender->GetId(), senderTpns[0], m_connection),
                              true,
                              "Expected the source reservation");
        Ptr<UbTransportChannel> receiverTp =
            m_receiverController->GetTransportChannelManager()->CreateReservedTpEndpoint(m_connection.tpn2);
        NS_TEST_ASSERT_MSG_NE(receiverTp, nullptr, "Expected one materialized receiver endpoint");
        const ConnectionStorageSnapshot materializedStorage =
            m_senderManager->GetConnectionStorageSnapshot();
        NS_TEST_ASSERT_MSG_EQ(materializedStorage.unmaterializedReservationRecords,
                              0u,
                              "A materialized connection should not count as fully compact");
        NS_TEST_ASSERT_MSG_EQ(materializedStorage.unmaterializedEndpointSlots,
                              0u,
                              "Materializing both endpoints should leave no reserved-only slot");
        NS_TEST_ASSERT_MSG_EQ(materializedStorage.activeLifecycleSidecars,
                              1u,
                              "Both endpoints should share one connection lifecycle sidecar");
        NS_TEST_ASSERT_MSG_EQ(materializedStorage.destroyCallbackBundles,
                              0u,
                              "Materialization alone should not allocate callback collections");
        Ptr<UbTransportChannel> senderTp = m_senderController->GetTransportChannelManager()->GetTp(m_connection.tpn1);
        NS_TEST_ASSERT_MSG_NE(senderTp, nullptr, "Expected one materialized sender endpoint");

        ConnectionLifecycleSnapshot before;
        NS_TEST_ASSERT_MSG_EQ(m_senderManager->GetConnectionLifecycleSnapshot(
                                  m_connection.tpn1, before),
                              true,
                              "Expected canonical connection lifecycle state");
        const UbLifecycleLeaseIdentity gate =
            UbLifecycleCoordinator::GetOrCreate(topo.sender)
                ->AcquireLease(senderTp->GetLifecycleOwner(),
                               UbLifecycleLeaseKind::TRANSPORT_WORK,
                               senderTp->GetLifecycleOwner());

        const UbDestroyStatus first = m_receiverManager->DestroyConnection(
            topo.receiver->GetId(),
            m_connection.tpn2,
            UbDestroyReason::EXPLICIT,
            MakeCallback(&UbExplicitConnectionDestroyAggregatesBothEndpointsTest::OnDestroyed,
                         this));
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(first),
                              static_cast<uint32_t>(UbDestroyStatus::PENDING),
                              "One busy endpoint should keep paired destroy pending");
        const UbDestroyStatus repeated = m_senderManager->DestroyConnection(
            topo.sender->GetId(),
            m_connection.tpn1,
            UbDestroyReason::ERROR,
            MakeCallback(&UbExplicitConnectionDestroyAggregatesBothEndpointsTest::OnDestroyed,
                         this));
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(repeated),
                              static_cast<uint32_t>(UbDestroyStatus::PENDING),
                              "Repeated either-side request should join the pending flow");
        ConnectionLifecycleSnapshot upgraded;
        NS_TEST_ASSERT_MSG_EQ(m_senderManager->GetConnectionLifecycleSnapshot(
                                  m_connection.tpn1, upgraded),
                              true,
                              "Repeated destroy should retain the canonical connection flow");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(upgraded.reason),
                              static_cast<uint32_t>(UbDestroyReason::ERROR),
                              "A stronger repeated request should upgrade the destroy reason");
        const ConnectionStorageSnapshot destroyingStorage =
            m_senderManager->GetConnectionStorageSnapshot();
        NS_TEST_ASSERT_MSG_EQ(destroyingStorage.destroyCallbackBundles,
                              1u,
                              "Pending destroy should allocate one callback bundle");
        NS_TEST_ASSERT_MSG_EQ(destroyingStorage.destroyCallbackEntries,
                              2u,
                              "Repeated destroy should aggregate both callbacks lazily");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(m_receiverManager->DestroyConnection(
                                  topo.receiver->GetId(),
                                  m_connection.tpn2,
                                  UbDestroyReason::EXPLICIT)),
                              static_cast<uint32_t>(UbDestroyStatus::PENDING),
                              "A weaker repeated request should stay on the same pending flow");
        NS_TEST_ASSERT_MSG_EQ(m_senderManager->GetConnectionLifecycleSnapshot(
                                  m_connection.tpn1, upgraded),
                              true,
                              "Weaker repeat should retain the canonical connection flow");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(upgraded.reason),
                              static_cast<uint32_t>(UbDestroyReason::ERROR),
                              "A weaker repeated request must not downgrade the destroy reason");
        const ConnectionStorageSnapshot noCallbackStorage =
            m_senderManager->GetConnectionStorageSnapshot();
        NS_TEST_ASSERT_MSG_EQ(noCallbackStorage.destroyCallbackBundles,
                              1u,
                              "A destroy request without a callback should not allocate a bundle");
        NS_TEST_ASSERT_MSG_EQ(noCallbackStorage.destroyCallbackEntries,
                              2u,
                              "A destroy request without a callback should not add an entry");
        NS_TEST_ASSERT_MSG_EQ(m_callbackCount,
                              0u,
                              "Connection callback must wait for both endpoint slots");

        UbLifecycleCoordinator::GetOrCreate(topo.sender)->ReleaseLease(gate);
        NS_TEST_ASSERT_MSG_EQ(m_callbackCount,
                              2u,
                              "Both pending callers should complete exactly once");
        NS_TEST_ASSERT_MSG_EQ(m_senderManager->GetCanonicalConnectionCountForTest(),
                              0u,
                              "Owner record should erase after both slots retire");

        const Connection retiredConnection = m_connection;
        const Ipv4Address retiredSourceIp =
            NodeIdToIp(topo.sender->GetId(), topo.senderPort->GetIfIndex());
        const Ipv4Address retiredDestinationIp =
            NodeIdToIp(topo.receiver->GetId(), topo.receiverPort->GetIfIndex());
        const UbInboundTpResolution retired =
            m_receiverController->GetTransportChannelManager()->ResolveInboundTp(
                retiredConnection.tpn1,
                retiredConnection.tpn2,
                retiredSourceIp,
                retiredDestinationIp,
                kUrmaWriteRegressionPriority);
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(retired.state),
                              static_cast<uint32_t>(UbInboundTpState::RETIRED_EXACT),
                              "Exact retired wire key should resolve as stale quarantine");
        NS_TEST_ASSERT_MSG_EQ(retired.endpoint,
                              nullptr,
                              "Retired quarantine must not retain TP backing");
        const UbInboundTpResolution retiredMismatch =
            m_receiverController->GetTransportChannelManager()->ResolveInboundTp(
                retiredConnection.tpn1 + 1,
                retiredConnection.tpn2,
                retiredSourceIp,
                retiredDestinationIp,
                kUrmaWriteRegressionPriority);
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(retiredMismatch.state),
                              static_cast<uint32_t>(UbInboundTpState::INVALID),
                              "A mismatched key sharing a retired TPN must remain invalid");

        Ptr<Packet> stalePacket = BuildInboundTpPacket(topo,
                                                       retiredConnection.tpn1,
                                                       retiredConnection.tpn2,
                                                       retiredSourceIp,
                                                       retiredDestinationIp,
                                                       kUrmaWriteRegressionPriority);
        topo.receiver->GetObject<UbSwitch>()->SwitchHandlePacket(topo.receiverPort, stalePacket);

        const std::vector<uint32_t> replacementTpns =
            m_senderManager->GetTpns(utils::GetTpnRuleT::BY_PEERNODE_PRIORITY,
                                     true,
                                     false,
                                     topo.sender->GetId(),
                                     topo.receiver->GetId(),
                                     UINT32_MAX,
                                     UINT32_MAX,
                                     kUrmaWriteRegressionPriority);
        NS_TEST_ASSERT_MSG_EQ(replacementTpns.size(), 1u, "Expected one replacement reservation");
        NS_TEST_ASSERT_MSG_NE(replacementTpns[0],
                              retiredConnection.tpn1,
                              "Retired source TPN must never be reused without a wire generation");
        ConnectionLifecycleSnapshot after;
        NS_TEST_ASSERT_MSG_EQ(
            m_senderManager->GetConnectionLifecycleSnapshot(replacementTpns[0], after),
            true,
            "Replacement reservation should create a canonical record");

        Connection replacement;
        NS_TEST_ASSERT_MSG_EQ(m_senderManager->TryGetLocalConnection(topo.sender->GetId(),
                                                                     replacementTpns[0],
                                                                     replacement),
                              true,
                              "Expected replacement source reservation");
        m_connection = replacement;
        Ptr<UbTransportChannel> replacementSender =
            m_senderController->GetTransportChannelManager()->GetTp(replacement.tpn1);
        const UbLifecycleLeaseIdentity lateGate =
            UbLifecycleCoordinator::GetOrCreate(topo.sender)
                ->AcquireLease(replacementSender->GetLifecycleOwner(),
                               UbLifecycleLeaseKind::TRANSPORT_WORK,
                               replacementSender->GetLifecycleOwner());
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(m_senderManager->DestroyConnection(
                topo.sender->GetId(),
                replacement.tpn1,
                UbDestroyReason::EXPLICIT,
                MakeCallback(&UbExplicitConnectionDestroyAggregatesBothEndpointsTest::OnDestroyed,
                             this))),
            static_cast<uint32_t>(UbDestroyStatus::PENDING),
            "Source endpoint gate should keep replacement destroy pending");
        NS_TEST_ASSERT_MSG_EQ(m_receiverController->GetTransportChannelManager()->CreateReservedTpEndpoint(replacement.tpn2),
                              nullptr,
                              "Closing connection should reject new application materialization");

        const UbInboundTpResolution drainOnlyResolution =
            m_receiverController->GetTransportChannelManager()->ResolveInboundTp(
                replacement.tpn1,
                replacement.tpn2,
                NodeIdToIp(topo.sender->GetId(), topo.senderPort->GetIfIndex()),
                NodeIdToIp(topo.receiver->GetId(), topo.receiverPort->GetIfIndex()),
                kUrmaWriteRegressionPriority);
        Ptr<UbTransportChannel> drainOnly = drainOnlyResolution.endpoint;
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(drainOnlyResolution.state),
                              static_cast<uint32_t>(UbInboundTpState::LIVE),
                              "Validated old inbound work should remain a live closing target");
        NS_TEST_ASSERT_MSG_NE(drainOnly,
                              nullptr,
                              "Validated old inbound work should materialize a drain-only endpoint");
        NS_TEST_ASSERT_MSG_EQ(drainOnly->IsAcceptingNewWorkForTest(),
                              false,
                              "Drain-only endpoint should never accept new application work");
        ConnectionLifecycleSnapshot closing;
        NS_TEST_ASSERT_MSG_EQ(m_senderManager->GetConnectionLifecycleSnapshot(
                                  replacement.tpn1, closing),
                              true,
                              "Closing connection should retain its canonical record");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(closing.slot2),
                              static_cast<uint32_t>(EndpointSlotState::DRAINING),
                              "Late endpoint should bind directly to the draining slot");
        Simulator::Stop(NanoSeconds(1));
        Simulator::Run();
        NS_TEST_ASSERT_MSG_EQ(m_receiverController->GetTransportChannelManager()->GetTp(replacement.tpn2),
                              nullptr,
                              "Idle drain-only endpoint should retire after the current handler");
        UbLifecycleCoordinator::GetOrCreate(topo.sender)->ReleaseLease(lateGate);
        NS_TEST_ASSERT_MSG_EQ(m_callbackCount,
                              3u,
                              "Late-packet flow should complete after both slots retire");

        Simulator::Destroy();
        Config::Reset();
    }

    Ptr<UbController> m_senderController;
    Ptr<UbController> m_receiverController;
    Ptr<TpConnectionManager> m_senderManager;
    Ptr<TpConnectionManager> m_receiverManager;
    Connection m_connection;
    UbLifecycleResourceIdentity m_destroyedIdentity;
    uint32_t m_callbackCount{0};
};

class UbIdentityConnectionDestroyStatusTest : public TestCase
{
  public:
    explicit UbIdentityConnectionDestroyStatusTest(bool remote)
        : TestCase(remote
                       ? "UnifiedBus - remote identity destroy reports stale and completed results"
                       : "UnifiedBus - local identity destroy returns synchronous completion"),
          m_remote(remote)
    {
    }

  private:
    void BeginDestroy()
    {
        m_initialStatuses.push_back(m_requestManager->DestroyConnection(
            m_requestedIdentity,
            UbDestroyReason::EXPLICIT,
            MakeCallback(&UbIdentityConnectionDestroyStatusTest::OnDestroyed, this)));
    }

    void OnDestroyed(UbLifecycleResourceIdentity identity, UbDestroyStatus status)
    {
        NS_TEST_ASSERT_MSG_EQ(identity,
                              m_requestedIdentity,
                              "Identity destroy callback must preserve the requested generation");
        m_callbackStatuses.push_back(status);
        if (m_remote && status == UbDestroyStatus::NOT_FOUND)
        {
            m_requestedIdentity = m_validIdentity;
            Simulator::ScheduleWithContext(m_requestNodeId, TimeStep(1), [this]() {
                BeginDestroy();
            });
        }
    }

    void DoRun() override
    {
        Config::Reset();
#ifdef NS3_MTP
        if (m_remote)
        {
            Config::SetDefault("ns3::UbLink::Delay", TimeValue(NanoSeconds(10)));
            MtpInterface::Enable(2, 2);
        }
#endif
        LocalTpTopology topo = BuildLocalTpTopology(true,
                                                    m_remote ? 1u : 0u,
                                                    m_remote ? 2u : 0u);

        Ptr<TpConnectionManager> senderManager =
            topo.sender->GetObject<UbController>()->GetTpConnManager();
        Ptr<TpConnectionManager> receiverManager =
            topo.receiver->GetObject<UbController>()->GetTpConnManager();
        const std::vector<UbLifecycleResourceIdentity> identities =
            senderManager->ReservePlannedTpnsForTraffic(true,
                                                        topo.sender->GetId(),
                                                        topo.receiver->GetId(),
                                                        kUrmaWriteRegressionPriority);
        NS_TEST_ASSERT_MSG_EQ(identities.size(),
                              1u,
                              "Identity destroy fixture requires one planned connection");
        m_validIdentity = identities.front();
        m_requestedIdentity = m_validIdentity;

        m_requestManager = receiverManager;
        m_requestNodeId = topo.receiver->GetId();
        if (m_remote)
        {
            ++m_requestedIdentity.generation;
            Simulator::ScheduleWithContext(topo.receiver->GetId(), TimeStep(1), [this]() {
                BeginDestroy();
            });
            Simulator::Stop(MicroSeconds(1));
            Simulator::Run();
            NS_TEST_ASSERT_MSG_EQ(m_initialStatuses.size(),
                                  2u,
                                  "Remote stale and valid destroy requests must both execute");
            NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(m_initialStatuses[0]),
                                  static_cast<uint32_t>(UbDestroyStatus::PENDING),
                                  "Cross-owner destroy must remain pending until the owner replies");
            NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(m_initialStatuses[1]),
                                  static_cast<uint32_t>(UbDestroyStatus::PENDING),
                                  "Cross-owner valid destroy must wait for the owner result");
            NS_TEST_ASSERT_MSG_EQ(m_callbackStatuses.size(),
                                  2u,
                                  "Remote stale and successful callbacks must each complete once");
            NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(m_callbackStatuses[0]),
                                  static_cast<uint32_t>(UbDestroyStatus::NOT_FOUND),
                                  "Remote stale destroy must report the owner's terminal status");
            NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(m_callbackStatuses[1]),
                                  static_cast<uint32_t>(UbDestroyStatus::COMPLETED),
                                  "Remote successful destroy must report completion");
        }
        else
        {
            BeginDestroy();
            NS_TEST_ASSERT_MSG_EQ(m_initialStatuses.size(), 1u, "Local destroy must execute once");
            NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(m_initialStatuses.front()),
                                  static_cast<uint32_t>(UbDestroyStatus::COMPLETED),
                                  "Execution-local identity destroy must return its actual status");
            NS_TEST_ASSERT_MSG_EQ(m_callbackStatuses.size(),
                                  1u,
                                  "Synchronous identity destroy must invoke its callback once");
            NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(m_callbackStatuses.front()),
                                  static_cast<uint32_t>(UbDestroyStatus::COMPLETED),
                                  "Synchronous identity destroy callback must report completion");
        }

        Simulator::Destroy();
        Config::Reset();
    }

    UbLifecycleResourceIdentity m_requestedIdentity;
    UbLifecycleResourceIdentity m_validIdentity;
    Ptr<TpConnectionManager> m_requestManager;
    std::vector<UbDestroyStatus> m_initialStatuses;
    std::vector<UbDestroyStatus> m_callbackStatuses;
    uint32_t m_requestNodeId{UINT32_MAX};
    bool m_remote{false};
};

class UbExplicitConnectionDestroyForceDisposeSafetyTest : public TestCase
{
  public:
    UbExplicitConnectionDestroyForceDisposeSafetyTest()
        : TestCase("UnifiedBus - pending endpoint destroy is safe during controller disposal")
    {
    }

    void DoRun() override
    {
        Config::Reset();
        LocalTpTopology topo = BuildLocalTpTopology();
        InstallStaticTpPair(topo);

        Ptr<UbController> senderController = topo.sender->GetObject<UbController>();
        Ptr<UbTransportChannel> senderTp =
            senderController->GetTransportChannelManager()->GetTp(kUrmaWriteRegressionSenderTpn);
        NS_TEST_ASSERT_MSG_NE(senderTp,
                              nullptr,
                              "Force-dispose fixture should materialize the source endpoint");
        Ptr<UbLifecycleCoordinator> coordinator =
            UbLifecycleCoordinator::GetOrCreate(topo.sender);
        const UbLifecycleLeaseIdentity gate =
            coordinator->AcquireLease(senderTp->GetLifecycleOwner(),
                                      UbLifecycleLeaseKind::TRANSPORT_WORK,
                                      senderTp->GetLifecycleOwner());

        Ptr<TpConnectionManager> receiverManager =
            topo.receiver->GetObject<UbController>()->GetTpConnManager();
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(receiverManager->DestroyConnection(
                topo.receiver->GetId(),
                kUrmaWriteRegressionReceiverTpn,
                UbDestroyReason::EXPLICIT)),
            static_cast<uint32_t>(UbDestroyStatus::PENDING),
            "The held transport lease should leave endpoint destroy pending");

        // The lease intentionally remains held. Controller disposal must not route the
        // pending endpoint callback through NodeList after NodeList teardown has started.
        (void)gate;
        Simulator::Destroy();
        Config::Reset();
    }
};

class UbExplicitConnectionDestroyDrainsAdmittedWriteTest : public TestCase
{
  public:
    explicit UbExplicitConnectionDestroyDrainsAdmittedWriteTest(bool mtp = false)
        : TestCase(mtp
                       ? "UnifiedBus - MTP cross-owner connection destroy drains an admitted write"
                       : "UnifiedBus - explicit connection destroy drains an admitted write"),
          m_mtp(mtp)
    {
    }

  private:
    void ObserveAdmission(uint32_t, uint32_t taskId, uint32_t)
    {
        if (taskId != kUrmaWriteRegressionTaskId || m_closeStarted)
        {
            return;
        }
        m_closeStarted = true;
        Simulator::ScheduleNow(
            &UbExplicitConnectionDestroyDrainsAdmittedWriteTest::BeginClose,
            this);
    }

    void BeginClose()
    {
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(m_connectionManager->DestroyConnection(
                m_senderNodeId,
                kUrmaWriteRegressionSenderTpn,
                UbDestroyReason::EXPLICIT,
                MakeCallback(&UbExplicitConnectionDestroyDrainsAdmittedWriteTest::OnDestroyed,
                             this))),
            static_cast<uint32_t>(UbDestroyStatus::PENDING),
            "An admitted write should keep connection destroy pending");
        Ptr<UbWqe> rejected = m_function->CreateWqe(m_senderNodeId,
                                                    m_receiverNodeId,
                                                    4096,
                                                    kUrmaWriteRegressionTaskId + 1,
                                                    UbTransactionOpcode::WRITE);
        NS_TEST_ASSERT_MSG_NE(
            static_cast<uint32_t>(
                m_function->SubmitWqe(rejected, kUrmaWriteRegressionJettyNum).status),
            static_cast<uint32_t>(UbWqeSubmissionStatus::ACCEPTED),
            "Connection drain must reject a new WQE before Jetty withdrawal");
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(m_function->DestroyJetty(kUrmaWriteRegressionJettyNum)),
            static_cast<uint32_t>(UbDestroyStatus::PENDING),
            "Jetty withdrawal should wait for the admitted write");
        NS_TEST_ASSERT_MSG_EQ(m_connectionDestroyed,
                              false,
                              "Connection retirement must wait for admitted work");
    }

    void OnWqeCompleted(UbWqeCompletion completion)
    {
        const uint32_t callbackLp = m_mtp ? Simulator::GetSystemId() : 0u;
        const uint32_t expectedLp = m_mtp ? 1u : 0u;
        NS_TEST_ASSERT_MSG_EQ(callbackLp,
                              expectedLp,
                              "Admitted write completion should execute on the sender owner LP");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(completion.outcome),
                              static_cast<uint32_t>(UbWorkOutcome::COMPLETED),
                              "Closing must preserve the admitted write outcome");
        m_writeCompleted = true;
    }

    void OnDestroyed(UbLifecycleResourceIdentity, UbDestroyStatus status)
    {
        const uint32_t callbackLp = m_mtp ? Simulator::GetSystemId() : 0u;
        const uint32_t expectedLp = m_mtp ? 1u : 0u;
        NS_TEST_ASSERT_MSG_EQ(callbackLp,
                              expectedLp,
                              "Connection completion should execute on the canonical owner LP");
        NS_TEST_ASSERT_MSG_EQ(static_cast<uint32_t>(status),
                              static_cast<uint32_t>(UbDestroyStatus::COMPLETED),
                              "Connection destroy callback should report completion");
        NS_TEST_ASSERT_MSG_EQ(m_writeCompleted,
                              true,
                              "Connection retirement must follow admitted write completion");
        Connection ignored;
        NS_TEST_ASSERT_MSG_EQ(m_connectionManager->TryGetLocalConnection(
                                  m_senderNodeId,
                                  kUrmaWriteRegressionSenderTpn,
                                  ignored),
                              false,
                              "Connection callback should follow sender view retirement");
        NS_TEST_ASSERT_MSG_EQ(m_receiverConnectionManager->TryGetLocalConnection(
                                  m_receiverNodeId,
                                  kUrmaWriteRegressionReceiverTpn,
                                  ignored),
                              false,
                              "Connection callback should follow receiver owner acknowledgement");
        m_connectionDestroyed = true;
    }

    void SubmitWrite()
    {
        m_function = m_senderController->GetUbFunction();
        Ptr<UbTransaction> transaction = m_senderController->GetUbTransaction();
        m_function->CreateJetty(m_senderNodeId,
                                m_receiverNodeId,
                                kUrmaWriteRegressionJettyNum);
        NS_TEST_ASSERT_MSG_EQ(transaction->JettyBindTp(m_senderNodeId,
                                                       m_receiverNodeId,
                                                       kUrmaWriteRegressionJettyNum,
                                                       false,
                                                       {kUrmaWriteRegressionSenderTpn}),
                              true,
                              "Delayed-destroy fixture should bind the reserved TP");

        Ptr<UbJetty> jetty = m_function->GetJetty(kUrmaWriteRegressionJettyNum);
        jetty->SetTaSegmentBytes(UB_WQE_TA_SEGMENT_BYTE / 2);
        jetty->SetWqeCompletionCallback(MakeCallback(
            &UbExplicitConnectionDestroyDrainsAdmittedWriteTest::OnWqeCompleted,
            this));
        Ptr<UbTransportChannel> senderTp =
            m_senderController->GetTransportChannelManager()->GetTp(
                kUrmaWriteRegressionSenderTpn);
        senderTp->TraceConnectWithoutContext(
            "WqeSegmentSendsNotify",
            MakeCallback(&UbExplicitConnectionDestroyDrainsAdmittedWriteTest::ObserveAdmission,
                         this));

        Ptr<UbWqe> wqe = m_function->CreateWqe(m_senderNodeId,
                                               m_receiverNodeId,
                                               UB_WQE_TA_SEGMENT_BYTE,
                                               kUrmaWriteRegressionTaskId,
                                               UbTransactionOpcode::WRITE);
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(m_function->SubmitWqe(wqe,
                                                        kUrmaWriteRegressionJettyNum)
                                      .status),
            static_cast<uint32_t>(UbWqeSubmissionStatus::ACCEPTED),
            "Delayed-destroy fixture should admit one real write operation");
    }

    void DoRun() override
    {
        Config::Reset();
#ifdef NS3_MTP
        if (m_mtp)
        {
            Config::SetDefault("ns3::UbLink::Delay", TimeValue(NanoSeconds(10)));
#ifdef NS3_MTP
            MtpInterface::Enable(2, 2);
#endif
        }
#endif
        LocalTpTopology topo =
            BuildLocalTpTopology(true, m_mtp ? 1u : 0u, m_mtp ? 2u : 0u);
#ifdef NS3_MTP
        if (m_mtp)
        {
#ifdef NS3_MTP
            NS_TEST_ASSERT_MSG_EQ(MtpInterface::RequireNodeLocalLpId(topo.sender->GetId()),
                                  1u,
                                  "Sender should execute on the first worker LP");
            NS_TEST_ASSERT_MSG_EQ(MtpInterface::RequireNodeLocalLpId(topo.receiver->GetId()),
                                  2u,
                                  "Receiver should execute on the second worker LP");
#endif
        }
#endif
        InstallStaticTpPair(topo);
        topo.sender->GetObject<UbController>()
            ->GetTransportChannelManager()
            ->GetTp(kUrmaWriteRegressionSenderTpn)
            ->SetMaxQueueSizeForTest(1);
        topo.receiver->GetObject<UbController>()
            ->GetTransportChannelManager()
            ->GetTp(kUrmaWriteRegressionReceiverTpn)
            ->SetMaxQueueSizeForTest(1);

        m_senderNodeId = topo.sender->GetId();
        m_receiverNodeId = topo.receiver->GetId();
        m_senderController = topo.sender->GetObject<UbController>();
        m_connectionManager = m_senderController->GetTpConnManager();
        m_receiverConnectionManager =
            topo.receiver->GetObject<UbController>()->GetTpConnManager();
        if (m_mtp)
        {
            Simulator::ScheduleWithContext(
                m_senderNodeId,
                NanoSeconds(1),
                &UbExplicitConnectionDestroyDrainsAdmittedWriteTest::SubmitWrite,
                this);
        }
        else
        {
            SubmitWrite();
        }

        Simulator::Stop(MilliSeconds(10));
        Simulator::Run();
        NS_TEST_ASSERT_MSG_EQ(m_closeStarted,
                              true,
                              "Delayed destroy should start after transport admission");
        NS_TEST_ASSERT_MSG_EQ(m_writeCompleted,
                              true,
                              "Admitted write should complete while the connection drains");
        NS_TEST_ASSERT_MSG_EQ(m_connectionDestroyed,
                              true,
                              "Both endpoint owners should acknowledge before the deadline");

        Simulator::Destroy();
        Config::Reset();
    }

    Ptr<TpConnectionManager> m_connectionManager;
    Ptr<TpConnectionManager> m_receiverConnectionManager;
    Ptr<UbController> m_senderController;
    Ptr<UbFunction> m_function;
    uint32_t m_senderNodeId{UINT32_MAX};
    uint32_t m_receiverNodeId{UINT32_MAX};
    bool m_closeStarted{false};
    bool m_writeCompleted{false};
    bool m_connectionDestroyed{false};
    bool m_mtp{false};
};

class UbTraceDirSetupTest : public TestCase
{
  public:
    UbTraceDirSetupTest()
        : TestCase("UnifiedBus - Trace directory setup tolerates missing runlog")
    {
    }

    void DoRun() override
    {
        namespace fs = std::filesystem;

        auto uniqueSuffix = std::to_string(
            std::chrono::steady_clock::now().time_since_epoch().count());
        fs::path caseDir = fs::temp_directory_path() / ("ub-trace-dir-test-" + uniqueSuffix);
        std::error_code ec;
        fs::remove_all(caseDir, ec);
        ec.clear();
        fs::create_directories(caseDir, ec);
        NS_TEST_ASSERT_MSG_EQ(ec.value(), 0, "Temporary case directory creation should succeed");

        fs::path configPath = caseDir / "network_attribute.txt";
        std::string tracePath = utils::UbUtils::PrepareTraceDir(configPath.string());

        NS_TEST_ASSERT_MSG_EQ(fs::exists(caseDir / "runlog"), true, "runlog directory should be created");
        NS_TEST_ASSERT_MSG_EQ(tracePath.empty(), false, "Returned trace path should not be empty");

        std::ofstream staleFile((caseDir / "runlog" / "stale.tr").string());
        staleFile << "stale";
        staleFile.close();

        tracePath = utils::UbUtils::PrepareTraceDir(configPath.string());
        NS_TEST_ASSERT_MSG_EQ(fs::exists(caseDir / "runlog" / "stale.tr"), false, "Existing runlog contents should be removed");
        NS_TEST_ASSERT_MSG_EQ(fs::exists(caseDir / "runlog"), true, "runlog directory should be recreated");

        fs::remove_all(caseDir, ec);
    }
};

class UbCsvTraceEndpointSemanticsTest : public TestCase
{
  public:
    UbCsvTraceEndpointSemanticsTest()
        : TestCase("UnifiedBus - CSV traces preserve missing packet endpoints")
    {
    }

    void DoRun() override
    {
        UbPacketTraceTag sourceTag;
        sourceTag.AddPortSendTrace(7, 3, 11);
        const PortTrace sourceTrace = sourceTag.GetPortTrace(7);
        NS_TEST_ASSERT_MSG_EQ(sourceTrace.recvPort,
                              UINT32_MAX,
                              "A source-only path entry must not invent a receive port");
        NS_TEST_ASSERT_MSG_EQ(sourceTrace.recvTime,
                              0u,
                              "A source-only path entry must not invent a receive timestamp");

        UbPacketTraceTag destinationTag;
        destinationTag.AddPortRecvTrace(8, 4, 22);
        const PortTrace destinationTrace = destinationTag.GetPortTrace(8);
        NS_TEST_ASSERT_MSG_EQ(destinationTrace.sendPort,
                              UINT32_MAX,
                              "A destination-only path entry must not invent a send port");
        NS_TEST_ASSERT_MSG_EQ(destinationTrace.sendTime,
                              0u,
                              "A destination-only path entry must not invent a send timestamp");

    }
};

