class UbCtpWireTaAckCompletesJettyTest : public TestCase
{
  public:
    UbCtpWireTaAckCompletesJettyTest()
        : TestCase("UnifiedBus - CTP wire TAACK completes the source Jetty")
    {
    }

  private:
    static constexpr uint32_t kJettyNum = 3;
    static constexpr uint32_t kTaskId = 77;

    void DoRun() override
    {
        Ptr<Node> node = BuildSinglePortCtpNode();
        Ptr<Node> remoteNode = CreateObject<Node>();
        InitNode(remoteNode, UB_DEVICE, 1);
        Ptr<UbController> controller = node->GetObject<UbController>();
        Ptr<UbFunction> function = controller->GetUbFunction();

        function->CreateJetty(0, 1, kJettyNum);
        Ptr<UbJetty> jetty = function->GetJetty(kJettyNum);
        m_completed = false;
        jetty->SetClientCallback(MakeCallback(&UbCtpWireTaAckCompletesJettyTest::OnTaskCompleted,
                                              this));
        Ptr<UbWqe> wqe =
            function->CreateWqe(0, 1, UB_MTU_BYTE, kTaskId, UbTransactionOpcode::WRITE);
        Ptr<UbCtpTransportService> service = controller->GetCtpTransportService();
        UbCtpEntityKey key{.srcEntityId = 1,
                           .dstNodeId = 1,
                           .dstEntityId = 1,
                           .vl = 7};
        wqe->SetPriority(key.vl);
        wqe->SetSport(0);
        wqe->SetDport(CTP_WILDCARD_PORT);
        NS_TEST_ASSERT_MSG_EQ(service->PrepareJetty(jetty, key), true, "keyed preparation");
        wqe->SetSrcEntityId(key.srcEntityId);
        wqe->SetDstEntityId(key.dstEntityId);
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(function->SubmitCtpWqe(wqe, kJettyNum, key).status),
            static_cast<uint32_t>(UbWqeSubmissionStatus::ACCEPTED),
            "test setup should admit the CTP WQE through the Transaction owner");
        service->StartJetty(jetty, key);
        NS_TEST_ASSERT_MSG_EQ((jetty->GetTaSsnSndNxtForTest() - jetty->GetTaSsnSndUnaForTest()),
                              1u,
                              "test setup should make one CTP transaction outstanding");

        UbCtpEntityKey ackWireKey{.srcEntityId = 1,
                                  .dstNodeId = 0,
                                  .dstEntityId = 1,
                                  .vl = 7};
        Ptr<Packet> ackPacket =
            BuildCtpResponsePacketFromNode(remoteNode,
                                           CreateCtpTaAckResponseSegment(0),
                                           ackWireKey);

        NS_TEST_ASSERT_MSG_EQ(service->HandleReceivedPacket(ackPacket, 0),
                              true,
                              "wire TAACK should be accepted by the CTP service");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndUnaForTest(),
                              1u,
                              "wire TAACK should advance the source Jetty ACK point");
        NS_TEST_ASSERT_MSG_EQ(m_completed,
                              true,
                              "wire TAACK should fire the Jetty completion callback");

        Simulator::Destroy();
    }

    void OnTaskCompleted(uint32_t completedTaskId, uint32_t completedJettyNum)
    {
        if (completedTaskId == kTaskId && completedJettyNum == kJettyNum)
        {
            m_completed = true;
        }
    }

    bool m_completed{false};
};

class UbCtpWireTaAckContinuesInflightLimitedWqeTest : public TestCase
{
  public:
    UbCtpWireTaAckContinuesInflightLimitedWqeTest()
        : TestCase("UnifiedBus - CTP wire TAACK continues an inflight-limited WQE")
    {
    }

  private:
    static constexpr uint32_t kJettyNum = 5;
    static constexpr uint32_t kTaskId = 90;

    void DoRun() override
    {
        Ptr<Node> node = BuildSinglePortCtpNode();
        Ptr<Node> remoteNode = CreateObject<Node>();
        InitNode(remoteNode, UB_DEVICE, 1);
        Ptr<UbController> controller = node->GetObject<UbController>();
        Ptr<UbFunction> function = controller->GetUbFunction();
        Ptr<UbTransaction> transaction = controller->GetUbTransaction();
        Ptr<UbCtpTransportService> service = controller->GetCtpTransportService();
        UbCtpEntityKey key{.srcEntityId = 1, .dstNodeId = 1, .dstEntityId = 1, .vl = 7};

        function->CreateJetty(0, key.dstNodeId, kJettyNum);
        Ptr<UbJetty> jetty = function->GetJetty(kJettyNum);
        jetty->SetAttribute("UbJettyInflightMax", UintegerValue(1));
        jetty->SetWqeCompletionCallback(
            MakeCallback(&UbCtpWireTaAckContinuesInflightLimitedWqeTest::OnCompletion, this));

        Ptr<UbWqe> wqe = function->CreateWqe(0,
                                             key.dstNodeId,
                                             2u * UbCtpTransportConstraints{}.maxSegmentBytes,
                                             kTaskId,
                                             UbTransactionOpcode::WRITE);
        wqe->SetPriority(key.vl);
        wqe->SetSport(0);
        wqe->SetDport(CTP_WILDCARD_PORT);
        NS_TEST_ASSERT_MSG_EQ(service->PrepareJetty(jetty, key), true, "keyed preparation");
        wqe->SetSrcEntityId(key.srcEntityId);
        wqe->SetDstEntityId(key.dstEntityId);
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(function->SubmitCtpWqe(wqe, kJettyNum, key).status),
            static_cast<uint32_t>(UbWqeSubmissionStatus::ACCEPTED),
            "Multi-segment CTP WQE should enter the inflight-limited Jetty");

        service->StartJetty(jetty, key);
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndNxtForTest(),
                              1u,
                              "Only the first CTP WQE segment should enter the Jetty window");
        NS_TEST_ASSERT_MSG_EQ((jetty->GetTaSsnSndNxtForTest() - jetty->GetTaSsnSndUnaForTest()),
                              1u,
                              "Only the first CTP segment should occupy the entity window");

        UbCtpEntityKey ackWireKey{.srcEntityId = 1, .dstNodeId = 0, .dstEntityId = 1, .vl = key.vl};
        NS_TEST_ASSERT_MSG_EQ(service->HandleReceivedPacket(
                                  BuildCtpResponsePacketFromNode(remoteNode,
                                                                 CreateCtpTaAckResponseSegment(0),
                                                                 ackWireKey),
                                  0),
                              true,
                              "First wire TAACK should be accepted");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndUnaForTest(),
                              1u,
                              "First wire TAACK should release one Jetty window slot");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndNxtForTest(),
                              2u,
                              "First wire TAACK should admit the next WQE segment exactly once");
        NS_TEST_ASSERT_MSG_EQ((jetty->GetTaSsnSndNxtForTest() - jetty->GetTaSsnSndUnaForTest()),
                              1u,
                              "The continued CTP segment should occupy the released entity slot");

        NS_TEST_ASSERT_MSG_EQ(service->HandleReceivedPacket(
                                  BuildCtpResponsePacketFromNode(remoteNode,
                                                                 CreateCtpTaAckResponseSegment(1),
                                                                 ackWireKey),
                                  0),
                              true,
                              "Second wire TAACK should be accepted");
        NS_TEST_ASSERT_MSG_EQ(m_completions,
                              1u,
                              "The multi-segment CTP WQE should complete exactly once");
        NS_TEST_ASSERT_MSG_EQ(transaction->GetResidentOperationCount(),
                              0u,
                              "The CTP operation should retire after both TAACKs");
        NS_TEST_ASSERT_MSG_EQ(transaction->GetResidentSegmentCount(),
                              0u,
                              "Both CTP segments should retire after their TAACKs");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetActiveWqeCount(),
                              0u,
                              "The completed CTP WQE should leave the Jetty");

        Simulator::Destroy();
    }

    void OnCompletion(UbWqeCompletion completion)
    {
        if (completion.wqeId == kTaskId && completion.outcome == UbWorkOutcome::COMPLETED)
        {
            ++m_completions;
        }
    }

    uint32_t m_completions{0};
};

class UbCtpOutOfOrderWireTaAckCompletesContiguousJettyRangeTest : public TestCase
{
  public:
    UbCtpOutOfOrderWireTaAckCompletesContiguousJettyRangeTest()
        : TestCase("UnifiedBus - CTP wire TAACK completes contiguous Jetty range after out-of-order ACK")
    {
    }

  private:
    static constexpr uint32_t kJettyNum = 4;

    void DoRun() override
    {
        Ptr<Node> node = BuildSinglePortCtpNode();
        Ptr<Node> remoteNode = CreateObject<Node>();
        InitNode(remoteNode, UB_DEVICE, 1);
        Ptr<UbController> controller = node->GetObject<UbController>();
        Ptr<UbFunction> function = controller->GetUbFunction();

        function->CreateJetty(0, 1, kJettyNum);
        Ptr<UbJetty> jetty = function->GetJetty(kJettyNum);
        jetty->SetClientCallback(
            MakeCallback(&UbCtpOutOfOrderWireTaAckCompletesContiguousJettyRangeTest::
                             OnTaskCompleted,
                         this));
        Ptr<UbWqe> wqe =
            function->CreateWqe(0,
                                1,
                                2u * UbCtpTransportConstraints{}.maxSegmentBytes,
                                kTaskId,
                                UbTransactionOpcode::WRITE);
        Ptr<UbCtpTransportService> service = controller->GetCtpTransportService();
        UbCtpEntityKey key{.srcEntityId = 1,
                           .dstNodeId = 1,
                           .dstEntityId = 1,
                           .vl = 7};
        wqe->SetPriority(key.vl);
        wqe->SetSport(0);
        wqe->SetDport(CTP_WILDCARD_PORT);
        NS_TEST_ASSERT_MSG_EQ(service->PrepareJetty(jetty, key), true, "keyed preparation");
        wqe->SetSrcEntityId(key.srcEntityId);
        wqe->SetDstEntityId(key.dstEntityId);
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(function->SubmitCtpWqe(wqe, kJettyNum, key).status),
            static_cast<uint32_t>(UbWqeSubmissionStatus::ACCEPTED),
            "test setup should admit the CTP WQE through the Transaction owner");
        service->StartJetty(jetty, key);
        NS_TEST_ASSERT_MSG_EQ((jetty->GetTaSsnSndNxtForTest() - jetty->GetTaSsnSndUnaForTest()),
                              2u,
                              "test setup should make both CTP transactions outstanding");

        UbCtpEntityKey ackWireKey{.srcEntityId = 1,
                                  .dstNodeId = 0,
                                  .dstEntityId = 1,
                                  .vl = 7};
        NS_TEST_ASSERT_MSG_EQ(service->HandleReceivedPacket(
                                  BuildCtpResponsePacketFromNode(
                                      remoteNode,
                                      CreateCtpTaAckResponseSegment(1),
                                      ackWireKey),
                                  0),
                              true,
                              "out-of-order TAACK should be accepted");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndUnaForTest(),
                              0u,
                              "out-of-order TAACK must wait for the base TASSN");
        NS_TEST_ASSERT_MSG_EQ(m_completed,
                              false,
                              "WQE should not complete while the base TASSN is missing");

        NS_TEST_ASSERT_MSG_EQ(service->HandleReceivedPacket(
                                  BuildCtpResponsePacketFromNode(
                                      remoteNode,
                                      CreateCtpTaAckResponseSegment(0),
                                      ackWireKey),
                                  0),
                              true,
                              "base TAACK should complete the contiguous range");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndUnaForTest(),
                              2u,
                              "base TAACK should advance through the already ACKed TASSN");
        NS_TEST_ASSERT_MSG_EQ(m_completed,
                              true,
                              "WQE should complete after both logical TASSNs are contiguous");

        Simulator::Destroy();
    }

    void OnTaskCompleted(uint32_t completedTaskId, uint32_t completedJettyNum)
    {
        if (completedTaskId == kTaskId && completedJettyNum == kJettyNum)
        {
            m_completed = true;
        }
    }

    static constexpr uint32_t kTaskId = 88;
    bool m_completed{false};
};

class UbCtpTerminalRetiresWaitingJettyWqesTest : public TestCase
{
  public:
    UbCtpTerminalRetiresWaitingJettyWqesTest()
        : TestCase("CTP abandonment retires waiting WQEs and requires a new requester")
    {
    }

  private:
    static constexpr uint32_t kJettyNum = 6;
    static constexpr uint32_t kFirstTaskId = 96;
    static constexpr uint32_t kSecondTaskId = 97;

    void DoRun() override
    {
        Ptr<Node> node = BuildSinglePortCtpNode();
        Ptr<Node> peer = CreateObject<Node>();
        InitNode(peer, UB_DEVICE, 1);
        Ptr<UbController> controller = node->GetObject<UbController>();
        Ptr<UbFunction> function = controller->GetUbFunction();
        Ptr<UbTransaction> transaction = controller->GetUbTransaction();
        Ptr<UbCtpTransportService> service = controller->GetCtpTransportService();
        UbCtpEntityKey key{.srcEntityId = 1,
                           .dstNodeId = peer->GetId(),
                           .dstEntityId = 1,
                           .vl = 7};

        function->CreateJetty(0, key.dstNodeId, kJettyNum);
        Ptr<UbJetty> jetty = function->GetJetty(kJettyNum);
        jetty->SetAttribute("UbJettyInflightMax", UintegerValue(1));
        jetty->SetTaSegmentBytes(64);
        jetty->SetWqeCompletionCallback(
            MakeCallback(&UbCtpTerminalRetiresWaitingJettyWqesTest::
                             OnCompletion,
                         this));

        Ptr<UbWqe> first = function->CreateWqe(0,
                                               key.dstNodeId,
                                               64,
                                               kFirstTaskId,
                                               UbTransactionOpcode::WRITE);
        Ptr<UbWqe> second = function->CreateWqe(0,
                                                key.dstNodeId,
                                                64,
                                                kSecondTaskId,
                                                UbTransactionOpcode::WRITE);
        first->SetPriority(key.vl);
        second->SetPriority(key.vl);
        first->SetSport(0);
        first->SetDport(CTP_WILDCARD_PORT);
        second->SetSport(0);
        second->SetDport(CTP_WILDCARD_PORT);
        NS_TEST_ASSERT_MSG_EQ(service->PrepareJetty(jetty, key), true, "keyed preparation");
        first->SetSrcEntityId(key.srcEntityId);
        first->SetDstEntityId(key.dstEntityId);
        second->SetSrcEntityId(key.srcEntityId);
        second->SetDstEntityId(key.dstEntityId);
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(function->SubmitCtpWqe(first, kJettyNum, key).status),
            static_cast<uint32_t>(UbWqeSubmissionStatus::ACCEPTED),
            "First CTP WQE should enter the Jetty");
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(function->SubmitCtpWqe(second, kJettyNum, key).status),
            static_cast<uint32_t>(UbWqeSubmissionStatus::ACCEPTED),
            "Second CTP WQE should wait in the same Jetty");
        service->StartJetty(jetty, key);

        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndNxtForTest(),
                              1u,
                              "Jetty inflight limit should admit only the first CTP WQE");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndUnaForTest(),
                              0u,
                              "The first CTP segment should remain unacknowledged");
        NS_TEST_ASSERT_MSG_EQ(transaction->GetActiveOperationCount(),
                              2u,
                              "Both CTP WQEs should remain lifecycle-managed before terminal cleanup");

        const auto oldRcid = *transaction->GetCtpRequesterRcid(kJettyNum);
        transaction->CompleteWqeOperation(kJettyNum, kFirstTaskId, UbWorkOutcome::CANCELED);
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndNxt(), 1u,
                              "abandonment cannot dispatch waiting work in the same generation");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndUna(), 1u, "retire the admitted segment");
        NS_TEST_ASSERT_MSG_EQ(function->GetJetty(kJettyNum), nullptr, "retire exact old requester");
        NS_TEST_ASSERT_MSG_EQ(transaction->GetActiveOperationCount(), 0u, "both WQEs retired");
        NS_TEST_ASSERT_MSG_EQ(transaction->GetResidentSegmentCount(), 0u, "no old segment backing");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetActiveWqeCount(), 0u, "remove both old WQEs");
        NS_TEST_ASSERT_MSG_EQ(service->GetQueuedPacketCountForTest(key), 0u,
                              "remove the old unsent request");
        NS_TEST_ASSERT_MSG_EQ(m_failedCompletions, 2u, "accepted WQEs fail exactly once");
        service->TryContinueJettyTransmission(key);
        service->TryContinueJettyTransmission(key);
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndNxt(), 1u, "no cleanup-induced resurrection");

        function->CreateJetty(node->GetId(), key.dstNodeId, kJettyNum);
        auto replacement = function->GetJetty(kJettyNum);
        NS_TEST_ASSERT_MSG_EQ(service->PrepareJetty(replacement, key), true,
                              "prepare new requester");
        NS_TEST_ASSERT_MSG_NE(*transaction->GetCtpRequesterRcid(kJettyNum), oldRcid,
                              "new generation uses fresh RCID");
        auto next = CreateCtpWqeForKey(function, node->GetId(), key, kSecondTaskId + 1);
        next->SetSport(0);
        NS_TEST_ASSERT_MSG_EQ(static_cast<int>(function->SubmitCtpWqe(next, kJettyNum, key).status),
                              0, "new generation can continue useful work");
        service->GetOrCreateQueue(key, 0, key.vl)->GetNextPacket();
        service->CompleteFromTaAckForTest(kJettyNum, 0);
        NS_TEST_ASSERT_MSG_EQ(replacement->GetTaSsnSndUna(), 1u, "new work completes normally");
        NS_TEST_ASSERT_MSG_EQ(transaction->GetActiveOperationCount(), 0u, "all new backing drains");
        NS_TEST_ASSERT_MSG_EQ(m_failedCompletions, 2u, "old terminals remain exactly once");

        Simulator::Destroy();
    }

    void OnCompletion(UbWqeCompletion completion)
    {
        if ((completion.wqeId == kFirstTaskId || completion.wqeId == kSecondTaskId) &&
            completion.outcome == UbWorkOutcome::FAILED)
        {
            ++m_failedCompletions;
        }
    }

    uint32_t m_failedCompletions{0};
};

class UbCtpOutOfOrderWireTaAckTracesArrivalTest : public TestCase
{
  public:
    UbCtpOutOfOrderWireTaAckTracesArrivalTest()
        : TestCase("UnifiedBus - CTP out-of-order wire TAACK traces arrival immediately")
    {
    }

  private:
    void DoRun() override
    {
        Ptr<Node> node = BuildSinglePortCtpNode();
        Ptr<Node> remoteNode = CreateObject<Node>();
        InitNode(remoteNode, UB_DEVICE, 1);
        Ptr<UbController> controller = node->GetObject<UbController>();
        Ptr<UbFunction> function = controller->GetUbFunction();

        function->CreateJetty(0, 1, kJettyNum);
        Ptr<UbJetty> jetty = function->GetJetty(kJettyNum);
        Ptr<UbWqe> wqe =
            function->CreateWqe(0,
                                1,
                                2u * UbCtpTransportConstraints{}.maxSegmentBytes,
                                kTaskId,
                                UbTransactionOpcode::WRITE);
        Ptr<UbCtpTransportService> service = controller->GetCtpTransportService();
        service->TraceConnectWithoutContext(
            "LastPacketACKsNotify",
            MakeCallback(&UbCtpOutOfOrderWireTaAckTracesArrivalTest::OnLastPacketAck, this));

        UbCtpEntityKey key{.srcEntityId = 1,
                           .dstNodeId = 1,
                           .dstEntityId = 1,
                           .vl = 7};
        wqe->SetPriority(key.vl);
        wqe->SetSport(0);
        wqe->SetDport(CTP_WILDCARD_PORT);
        NS_TEST_ASSERT_MSG_EQ(service->PrepareJetty(jetty, key), true, "keyed preparation");
        wqe->SetSrcEntityId(key.srcEntityId);
        wqe->SetDstEntityId(key.dstEntityId);
        NS_TEST_ASSERT_MSG_EQ(
            static_cast<uint32_t>(function->SubmitCtpWqe(wqe, kJettyNum, key).status),
            static_cast<uint32_t>(UbWqeSubmissionStatus::ACCEPTED),
            "test setup should admit the CTP WQE through the Transaction owner");
        service->StartJetty(jetty, key);
        NS_TEST_ASSERT_MSG_EQ((jetty->GetTaSsnSndNxtForTest() - jetty->GetTaSsnSndUnaForTest()),
                              2u,
                              "test setup should make both CTP transactions outstanding");

        UbCtpEntityKey ackWireKey{.srcEntityId = 1,
                                  .dstNodeId = 0,
                                  .dstEntityId = 1,
                                  .vl = 7};
        NS_TEST_ASSERT_MSG_EQ(service->HandleReceivedPacket(
                                  BuildCtpResponsePacketFromNode(
                                      remoteNode,
                                      CreateCtpTaAckResponseSegment(1),
                                      ackWireKey),
                                  0),
                              true,
                              "out-of-order TAACK should be accepted");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndUnaForTest(),
                              0u,
                              "out-of-order TAACK should not advance contiguous Jetty completion");
        NS_TEST_ASSERT_MSG_EQ(m_ackedTaSsn,
                              1u,
                              "out-of-order TAACK should trace the ACKed logical TASSN immediately");

        Simulator::Destroy();
    }

    void OnLastPacketAck(uint32_t,
                         uint32_t,
                         uint32_t,
                         uint32_t,
                         uint32_t,
                         uint32_t,
                         uint32_t,
                         uint32_t taSsn,
                         uint32_t,
                         uint32_t,
                         uint32_t)
    {
        m_ackedTaSsn = taSsn;
    }

    static constexpr uint32_t kJettyNum = 5;
    static constexpr uint32_t kTaskId = 89;
    uint32_t m_ackedTaSsn{std::numeric_limits<uint32_t>::max()};
};

