class UbCtpIdleReprepareKeepsJettyProgressTest : public TestCase
{
  public:
    UbCtpIdleReprepareKeepsJettyProgressTest()
        : TestCase("CTP idle unprepare and reprepare retain Jetty cursor and RCID") {}
    void DoRun() override
    {
        auto node = BuildSinglePortCtpNode();
        auto peer = BuildSinglePortCtpNode();
        auto controller = node->GetObject<UbController>();
        auto service = controller->GetCtpTransportService();
        const UbCtpEntityKey key{1, peer->GetId(), 1, 7};
        auto jetty = SubmitCtpFixture(node, key);
        auto rcid = controller->GetUbTransaction()->GetCtpRequesterRcid(0);
        NS_TEST_ASSERT_MSG_EQ(service->UnprepareJetty(0), false, "active work prevents unprepare");
        NS_TEST_ASSERT_MSG_NE(service->GetOrCreateQueue(key, 0, key.vl)->GetNextPacket(), nullptr,
                              "model request handoff before injecting its response");
        service->CompleteFromTaAckForTest(0, 0);
        NS_TEST_ASSERT_MSG_EQ(controller->GetUbTransaction()->GetResidentSegmentCount(), 0u,
                              "sole segment backing retired");
        NS_TEST_ASSERT_MSG_EQ(service->UnprepareJetty(0), true, "idle unprepare");
        NS_TEST_ASSERT_MSG_EQ(service->PrepareJetty(jetty, key), true, "reprepare same generation");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndNxtForTest(), 1u, "send cursor retained");
        NS_TEST_ASSERT_MSG_EQ(jetty->GetTaSsnSndUnaForTest(), 1u, "completion cursor retained");
        NS_TEST_ASSERT_MSG_EQ(*controller->GetUbTransaction()->GetCtpRequesterRcid(0), *rcid,
                              "same generation retains RCID");
        Simulator::Destroy();
    }
};

class UbCtpCongestionKeyUsesDestinationAndVlTest : public TestCase
{
  public:
    UbCtpCongestionKeyUsesDestinationAndVlTest()
        : TestCase("UnifiedBus - CTP congestion contexts aggregate by destination and VL")
    {
    }

  private:
    void DoRun() override
    {
        Ptr<Node> localNode = BuildSinglePortCtpNode();
        Ptr<Node> remoteNode1 = CreateObject<Node>();
        Ptr<Node> remoteNode2 = CreateObject<Node>();
        Ptr<UbCtpTransportService> service =
            localNode->GetObject<UbController>()->GetCtpTransportService();

        UbCtpEntityKey entity1{.srcEntityId = 1,
                               .dstNodeId = remoteNode1->GetId(),
                               .dstEntityId = 50,
                               .vl = 7};
        UbCtpEntityKey entity2 = entity1;
        entity2.srcEntityId = 2;
        service->RecordCnpForTest(entity1);
        service->RecordCnpForTest(entity2);
        NS_TEST_ASSERT_MSG_EQ(service->GetCongestionStateCountForTest(),
                              1u,
                              "source Entities sharing destination and VL should share congestion");

        UbCtpEntityKey otherVl = entity1;
        otherVl.vl = 6;
        service->RecordCnpForTest(otherVl);
        NS_TEST_ASSERT_MSG_EQ(service->GetCongestionStateCountForTest(),
                              2u,
                              "different VLs must keep separate congestion contexts");

        UbCtpEntityKey otherDestination = entity1;
        otherDestination.dstNodeId = remoteNode2->GetId();
        service->RecordCnpForTest(otherDestination);
        NS_TEST_ASSERT_MSG_EQ(service->GetCongestionStateCountForTest(),
                              3u,
                              "the same destination Entity on different nodes must stay separate");

        UbCtpEntityKey otherDestinationEntity = entity1;
        otherDestinationEntity.dstEntityId = 51;
        service->RecordCnpForTest(otherDestinationEntity);
        NS_TEST_ASSERT_MSG_EQ(service->GetCongestionStateCountForTest(),
                              4u,
                              "a different destination Entity should create its own context");

        UbCtpEntityKey reverseWireKey{.srcEntityId = 51,
                                      .dstNodeId = localNode->GetId(),
                                      .dstEntityId = 1,
                                      .vl = 7};
        NS_TEST_ASSERT_MSG_EQ(service->HandleReceivedPacket(
                                  BuildCtpCnpPacket(remoteNode1->GetId(), reverseWireKey),
                                  0),
                              true,
                              "reverse-direction CNP should parse through the production boundary");
        NS_TEST_ASSERT_MSG_EQ(service->GetCongestionStateCountForTest(),
                              4u,
                              "reverse normalization should find the outbound destination context");

        NS_TEST_ASSERT_MSG_EQ(service->HandleReceivedPacket(
                                  BuildCtpCnpPacket(remoteNode2->GetId(), reverseWireKey),
                                  0),
                              true,
                              "a second remote CNP should parse through the production boundary");
        NS_TEST_ASSERT_MSG_EQ(service->GetCongestionStateCountForTest(),
                              5u,
                              "reverse normalization must not cross destination-node contexts");

        Simulator::Destroy();
    }
};

